<template><div class="public-profile-shell"><header class="cloud-header"><a class="cloud-brand" href="https://pcln.top/"><BrandIcon /><strong>NexaMC</strong></a><a class="profile-home-link" href="https://pcln.top/">{{ $ui('返回网站 ↗') }}</a><LanguageControl /><ThemeControl /></header><main class="cloud-content public-profile"><form class="profile-search" @submit.prevent="search"><label>{{ $ui('用户 ID') }}<input v-model.trim="query" required maxlength="64" placeholder="@uid" /></label><button class="secondary-button">{{ $ui('查看主页') }}</button></form><p v-if="loading" role="status">{{ $ui('正在读取…') }}</p><p v-else-if="error" class="form-error" role="alert">{{ $ui(error) }}</p><template v-if="data"><section class="work-panel profile-hero"><span class="profile-avatar" aria-hidden="true">{{ data.profile.name[0]?.toUpperCase() }}</span><div><p class="eyebrow">{{ $ui('用户主页') }}</p><h1>{{ data.profile.name }}</h1><p>@{{ data.profile.uid }}</p></div></section><section class="work-panel"><h2>{{ $ui('公开作品') }}</h2><p v-if="!data.projects.length" class="store-muted">{{ $ui('暂无公开作品。') }}</p><a v-for="project in data.projects" :key="project.id" class="store-content-row" :href="'https://pcln.top'+storePath(project.kind,project.id)"><div><strong>{{ project.name }}</strong><p>{{ project.summary }}</p></div><span>→</span></a></section><section class="work-panel"><h2>{{ $ui('最近的公开评论') }}</h2><p v-if="!data.comments.length" class="store-muted">{{ $ui('暂无评论。') }}</p><article v-for="comment in data.comments" :key="comment.id" class="profile-comment"><a :href="'https://pcln.top'+storePath(comment.kind,comment.item_id)">{{ comment.project_name }}</a><p>{{ Array.from(comment.body).slice(0,200).join('') }}{{ Array.from(comment.body).length>200?'…':'' }}</p><small>{{ new Date(comment.created_at).toLocaleDateString($locale) }}</small></article></section></template></main></div></template>
<script setup lang="ts">
import {ref,watch,onBeforeUnmount} from 'vue';import{useRoute,useRouter}from'vue-router';import{store,storePath}from'@/api/store';import BrandIcon from '@/components/BrandIcon.vue';import LanguageControl from '@/components/LanguageControl.vue';import ThemeControl from '@/components/ThemeControl.vue';import '@/styles/store.css';
const route=useRoute(),router=useRouter(),query=ref(''),loading=ref(false),error=ref(''),data=ref<Awaited<ReturnType<typeof store.publicProfile>>>();let generation=0;
function search(){const value=query.value.replace(/^@/,'');if(/^[a-zA-Z0-9_-]{1,64}$/.test(value))void router.push('/@'+encodeURIComponent(value));}
watch(()=>route.params.uid,async value=>{const step=++generation;data.value=undefined;error.value='';query.value=typeof value==='string'?value:'';if(!query.value)return;loading.value=true;try{const profile=await store.publicProfile(query.value);if(step===generation){data.value=profile;if(profile.profile.id==='ghost'&&route.params.uid!=='ghost')void router.replace('/@ghost');}}catch(e){if(step===generation)error.value=e instanceof Error?e.message:'用户主页暂不可用';}finally{if(step===generation)loading.value=false;}},{immediate:true});onBeforeUnmount(()=>generation++);
</script>
<style scoped>.public-profile{max-width:1000px}.profile-home-link{margin-left:auto}.profile-search{display:flex;align-items:end;gap:12px;margin-bottom:24px;flex-wrap:wrap}.profile-search label{display:grid;gap:8px;font-size:13px}.profile-search input{padding:10px 12px;border:1px solid var(--market-border);border-radius:8px;background:var(--market-surface);color:var(--market-text)}.profile-hero{display:flex;align-items:center;gap:24px}.profile-avatar{display:grid;place-items:center;width:72px;height:72px;border-radius:50%;background:var(--market-accent-soft);color:var(--nc-accent);font-size:28px;flex-shrink:0}.profile-hero h1{overflow-wrap:anywhere}.profile-hero p{overflow-wrap:anywhere}.profile-comment{padding:20px 0;border-bottom:1px solid var(--market-border)}.profile-comment p{white-space:pre-wrap;overflow-wrap:anywhere;margin:8px 0}.profile-comment small{color:var(--market-muted)}@media(max-width:600px){.profile-hero{gap:12px}.profile-avatar{width:44px;height:44px;font-size:20px}.profile-home-link{font-size:12px}}</style>
